/* Read the same physical location in the picture, input and output. */
(() => {
 'use strict';
 const A=window.LessonArticle,ink='#324f70',blue='#23629a',red='#a44230';
 const p=s=>'<p>'+s+'</p>';
 const stroke=(d,c=ink,dash='')=>'<path d="'+d+'" fill="none" stroke="'+c+'" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="'+dash+'"/>';
 const label=(x,y,s)=>'<text x="'+x+'" y="'+y+'" text-anchor="middle" fill="'+ink+'">'+s+'</text>';
 const dot=(x,y)=>'<circle cx="'+x+'" cy="'+y+'" r="4" fill="white" stroke="'+blue+'" stroke-width="2.4"/>';
 const wall=(x,right=false)=>'<g transform="translate('+x+' 0) scale('+(right?-1:1)+' 1)">'+stroke('M0 32v50 m-9-38 9-9 m-9 22 9-9 m-9 22 9-9',blue)+'</g>';
 const figure=(alt,svg,caption)=>'<figure class="element-figure"><svg class="theory-lab-svg" dir="ltr" viewBox="0 0 340 138" role="img" aria-label="'+alt+'"><g font-family="system-ui,sans-serif" font-size="13">'+svg+'</g></svg><figcaption>'+caption+'</figcaption></figure>';
 const table=rows=>A.table(['入力のどこを見るか','図との対応'],rows,{narrow:true});
 function loads(face){
  const weights=face?[[1,2,2,2,1],[2,4,4,4,2],[1,2,2,2,1]]:[[1,2,2,2,1]];
  let art='';
  weights.forEach((row,r)=>row.forEach((w,c)=>{
   const x=44+62*c,y=face?26+38*r:64;
   if(c<4)art+=stroke('M'+x+' '+y+'h62',ink);
   if(face&&r<2)art+=stroke('M'+x+' '+y+'v38',ink);
  }));
  weights.forEach((row,r)=>row.forEach((w,c)=>{
   const x=44+62*c,y=face?26+38*r:64;
   art+='<circle cx="'+x+'" cy="'+y+'" r="'+(7+1.4*w)+'" fill="white" stroke="'+blue+'" stroke-width="2"/>'+label(x,y+4,w);
  }));
  return figure(face?'端面15点が負担する荷重の比':'先端辺5点が負担する荷重の比',art+(face?label(170,131,'Σw = 32     |F| = 18 N'):[61,62,63,64,65].map((g,i)=>label(44+62*i,101,'G'+g)).join('')),
   face?'先端面を正面から見た図。丸内は分担比です。四隅・辺・内部の順に1・2・4となり、内部のG368は18×4/32＝2.25 Nを受け持ちます。すべて下向きです。':'先端辺を正面から見た図。丸内は分担比、左からG61～65。両端の点には片側の区間だけ、内側の点には両隣の半区間ずつの荷重が集まります。');
 }
 function bending(){
  return figure('梁の根元の上向き反力と、荷重で下がる自由端',
   wall(45)+stroke('M45 58H285',ink,'6 4')+stroke('M45 58C118 58 212 77 285 99',blue)+dot(285,99)+
   stroke('M285 44v45m-5-7 5 7 5-7',red)+stroke('M45 104V70m-5 7 5-7 5 7',blue)+
   label(84,108,'+18 N')+label(282,35,'−18 N')+label(172,79,'X →')+label(253,125,'G13 · T3'),
   '破線が荷重を加える前、実線が変形後の模式形です。図では＋Zを上に取り、壁が梁を支える力と先端が下がる向きを別の矢印で示しています。');
 }
 function surfaces(){
  return figure('同じ断面の上面は引張、下面は圧縮となる片持ち板の側面',
   wall(46)+stroke('M46 47 Q154 47 285 84',red)+stroke('M46 64 Q154 64 285 101',blue)+
   stroke('M46 55 Q154 55 285 93',ink,'5 4')+stroke('M122 32v56',ink,'2 4')+
   dot(122,51)+dot(122,68)+label(161,27,'σₓ > 0')+label(155,104,'σₓ < 0')+
   stroke('M285 42v30m-5-7 5 7 5-7',red)+label(256,126,'X →'),
   '側面から見た変形の模式図です。縦の点線が読み取る断面。下向き荷重で、壁寄りの上面は引っ張られ、下面は押し縮められます。横の破線は板厚の中央です。');
 }
 function couple(){
  return figure('固定面の上部と下部の逆向きの力が作る反力モーメント',
   stroke('M232 33H136V98H232')+stroke('M136 33l-9 9m9 8-9 9m9 8-9 9m9 8-9 9',blue)+stroke('M111 65h133',ink,'4 4')+dot(136,38)+dot(136,93)+
   stroke('M132 38H73m8-5-8 5 8 5',blue)+stroke('M140 93h59m-8-5 8 5-8 5',blue)+
   label(95,26,'−Fₓ')+label(191,116,'+Fₓ')+label(263,46,'Z ↑')+label(263,87,'X →'),
   '固定面を横から見た模式図。上の層と下の層の反力は向きが逆でも、間隔があるので同じ向きに梁を回そうとします。この一組を偶力と呼びます。矢印は分布の模式表示で、各節点の実測値ではありません。');
 }
 function shape(id){
  const fixed=id==='both-fixed',added=id==='tip-mass',x=fixed?169:287;
  let art=wall(51)+(fixed?wall(287,true):'')+stroke('M51 55H287',ink,'5 4')+
   stroke(fixed?'M51 55C98 55 118 96 169 96S240 55 287 55':'M51 55C138 55 212 73 287 96',blue);
  if(added)art+='<rect x="278" y="86" width="18" height="18" fill="#ffe1ac" stroke="'+ink+'"/>';
  art+=dot(x,96)+label(51,118,'G1')+label(fixed?169:273,123,fixed?'G7 · T3':'G13 · T3')+(fixed?label(293,118,'G13'):'');
  if(added)art+=label(272,32,'+0.080 kg');
  return figure(fixed?'両端が静止し中央が大きく動く第1曲げ':added?'先端の質量と一緒に動く片持ちの第1曲げ':'固定端が静止し先端が大きく動く第1曲げ',art,
   '破線は元の中心線、実線は厚さ方向の第1曲げの形を見やすく描いた模式線です。白丸が読む位置です。線の高さは実際の振幅を表しません。');
 }
 const cases={
  beam:{
   goals:['同じ18 Nでも、力の釣合いと先端たわみで確かめられることの違いを説明できる。'],
   points:['左端を壁に固定し、自由な右端を下へ18 Nで押す。','中心線を使って表し、断面の幅と厚さから曲がりにくさを与える。','壁が押し返す力と、右端が下がる量を別々に読む。'],
   intro:'長さ360 mm、幅36 mm、厚さ6 mmの部材の先端を押し続けます。動きが落ち着いたとき、部材全体がどれだけたわむかを知りたい場面です。梁モデルでは断面の中心を結ぶ線を描き、断面の広がりは数値で与えます。',
   inputTitle:'中心線のどちらを固定し、どちらを押すか',input:[
    ['SPC=10 → SPC1','GRIDは節点、後ろの数字はその番号です。壁にあるG1は移動3方向（123）と回転3方向（456）を止めます。'],
    ['LOAD=40 → FORCE','右端G13に18 N。全体Z軸を上に取って方向を (0, 0, −1) とします。出力のT3がこのモデルのZ方向です。'],
    ['CBEAM → PBEAM','梁は長手がX、厚さがZ。向きベクトルを＋Zとして断面の置き方を定めます。この向きの曲がりにくさに使う断面二次モーメントは I1＝36×6³/12＝648 mm⁴ です。']
   ],resultTitle:'反力が合っても、たわみが合わないとき',draw:bending,
   reads:['SPCFORCESで要求した表（FORCES OF SINGLE-POINT CONSTRAINT）には、壁が部材に及ぼす支持反力が並びます。根元G1では、T3（Z方向の力）が＋18 Nなら下向きの荷重と釣り合います。R2はY軸まわりの反力モーメントで、壁が先端荷重の回転作用を打ち消すため−6,480 N·mmとなります。','DISPLACEMENT VECTORでG13のT3を読みます。細長い梁の手計算の目安は−6.17 mmです。反力が合うのに変位の絶対値が約1/36なら、荷重を変える前に断面の幅と厚さの向きを照合します。'],
   prompt:'壁の反力が18 Nなら、断面の向きも合っている？',answer:'この片持ち梁の反力は荷重と支持で決まります。幅と厚さを入れ替えても反力は同じですが、曲げ剛性が36倍になり、曲げたわみは約1/36になります。'
  },
  shell:{
   goals:['先端辺に力を分ける理由と、曲げ応力を読む二つの面を、同じ板の図で説明できる。'],
   points:['薄板の厚さの中央に面を置き、厚さは6 mmと別に指定する。','根元の辺を固定し、先端辺の5点で合計18 Nを受け持つ。','先端中央のたわみと、同じ断面の表裏の応力を読む。'],
   intro:'先端の真ん中だけでなく、板幅に沿ってどのようにたわむかを見たいとします。板の中央面を四角形に区切ると幅方向にも観測点を置けます。先端辺は幅36 mmで、等しい4区間に分かれています。図や入力に出てくるG63は、先端の中央にある節点63です。',
   inputTitle:'先端辺を4区間に分けると、なぜ荷重は5個か',inputFigure:()=>loads(false),input:[
    ['SPC=10 → SPC1','壁に接する辺のG1～5で移動と回転を止めます。中央1点だけにすると、辺の残りが動けます。'],
    ['LOAD=40 → FORCE','全荷重18 Nを図の重みの合計8で割ります。両端は各2.25 N、内側3点は各4.5 Nで、すべて−Zへ向けます。'],
    ['CQUAD4 → PSHELL','四角形の節点は中央面上にあります。PSHELLのTに厚さ6 mm、MID2に曲げを受け持つ材料70を指定します。']
   ],resultTitle:'板の「上」と出力の「表」を対応させる',draw:surfaces,
   reads:['変位表 DISPLACEMENT VECTORで先端中央G63のT3（この板の上下方向）を読みます。壁の反力はG1～5のT3を合計して＋18 Nと照合します。','STRESSESの同一要素・同一位置で、中央面からの距離（FIBER DISTANCE）が異なる2行を読みます。節点順が決める法線と実物の上面を対応させ、長手X方向の応力を比較します。相当応力だけでは引張と圧縮の符号が分かりません。'],
   prompt:'板の法線が反転したときも、同じ出力行が上面になる？',answer:'この板では、法線と同じ側が正の厚さ位置です。法線を反転すると、その側が実物のどちらに当たるかも入れ替わります。比較する断面、物理的な面、応力方向を先にそろえます。'
  },
  solid:{
   goals:['回転の欄を使わず、固定面の節点に出た力から曲げを確かめられる。'],
   points:['厚さも含めて立体を区切り、固定する面と押す面を決める。','先端面の15点に、各点が受け持つ面積に応じて力を配る。','固定面に働く左右向きの力と、その力が働く高さを組にして読む。'],
   intro:'厚さの中や壁際の力の流れまで見たいときは、部材を六面体で表します。根元にも先端にも幅5点×厚さ3点が並びます。端面全体を押す条件は、この15点の位置と力で表現できます。',
   inputTitle:'端面の四隅・辺・内部で荷重を配り分ける',inputFigure:()=>loads(true),input:[
    ['CHEXA → GRID・PSOLID','厚さ6 mmは上下の節点の座標差で決まります。PSOLIDから材料を参照します。'],
    ['SPC=10 → SPC1','根元面G1～15の各点で、X・Y・Z方向の移動（123）を止めます。ソリッドは離れた節点の移動差で断面の回転を表します。'],
    ['LOAD=40 → FORCE','先端面G361～375で−Zに合計18 N。等間隔の面では、四隅1、辺2、内部4の重みで配ると、各小面に同じ割合の荷重が掛かります。']
   ],resultTitle:'固定面の反力を、位置と組にして読む',draw:couple,
   reads:['DISPLACEMENT VECTORでは先端面の中央G368のT3、SPCFORCESでは根元15点のT3の和を読みます。後者の目安は＋18 Nです。','同じ座標系で根元面の中心を基準に取ります。各点はx＝0なので、Y軸まわりでは「中心からの符号付き高さz × X方向反力（T1）」を15点分足します。上と下で符号が逆の力も、この積では同じ向きに効きます。根元反力モーメントは−18×360＝−6,480 N·mmです。'],
   prompt:'固定端の角の応力だけが細分化のたびに増えた。板全体が悪化した？',answer:'角の最大値と、一定の断面の応力は別々に追います。根元から同じ距離の同じ面を選んで比較し、合反力・先端たわみも確認します。理想的に固定した角の局所ピークだけでは、実際の取付部の強度を判定できません。'
  },
  baseline:{
   goals:['最初の曲げが何Hzか、どこが動くかを、別々の出力から対応させられる。'],
   points:['梁の片端を固定し、自由な先端が上下に揺れる形を見る。','1秒あたりの往復回数が固有振動数。各点がどちらへどの割合で動くかがモード形。','振動数の行と同じモード番号を使って形を確認する。'],
   intro:'片端を固定した薄い梁の先を少したわませて離すと、先端が上下に往復します。ここで求めるのは、梁が自然に揺れやすい速さと形です。押し続ける力の大きさを指定する必要はありません。',
   inputTitle:'支持・質量・求める形の数を順に決める',input:[
    ['SPC=10 → SPC1','G1だけを固定し、反対のG13は自由にします。'],
    ['PBEAM・MAT1','断面と材料で曲がりにくさを、密度×体積で質量を定めます。N・mm・sで総質量は0.000209952 t（約0.210 kg）です。'],
    ['METHOD=30 → EIGRL 30','30は抽出条件を選ぶ番号です。ND=12で低い方から12個の振動形を求めます。12 Hzという上限ではありません。']
   ],resultTitle:'振動数の行から、対応する梁の形へ',draw:()=>shape('baseline'),
   reads:['F06は計算結果を表で読むテキストです。REAL EIGENVALUESで MODE NO.（モード番号）と CYCLES（Hz）を読みます。最初の厚さ方向の曲げは細長い梁の理論で約38.08 Hz。約0.026秒で1往復する速さです。','同じ番号のREAL EIGENVECTORで、壁のG1と自由端G13のT3（上下）を比較します。端が大きく動く形かを確かめます。この表の数字は形の比率です。'],
   prompt:'表示倍率を2倍にして、先端が倍の高さに見えた。振動数も変わる？',answer:'同じモード番号のCYCLESは変わりません。倍率で変わるのは描く高さです。実際に何mm揺れるかを求めるには、力の大きさ・周波数・減衰などが必要です。'
  },
  'tip-mass':{
   goals:['先端に部品を追加した影響を、総質量と同じ曲げモードの振動数で確かめられる。'],
   points:['基準梁の先端に80 gの部品を取り付け、支持と断面を保つ。','質量が増えた場所と、もともと大きく揺れる場所を重ねて見る。','基準梁と同じ方向に曲がる形を選び、その振動数を比較する。'],
   intro:'片持ち梁の先端に小さなセンサーを取り付けます。先端が上下に往復するたびにセンサーも動くため、最初の曲げでは往復が遅くなります。取り付けで梁の硬さは変化しないと仮定します。',
   inputTitle:'80 gを先端へ一度だけ加える',input:[
    ['CONM2 201 → G13','80 g＝0.08 kg＝0.00008 t。N・mm・sで入力するM欄は0.00008です。重力を掛けたN値を入れると、異なる質量になります。'],
    ['MAT1・SPC1','梁の密度と根元G1の固定は基準と同じです。密度も増やすと、先端だけに質量を足す比較ができません。'],
    ['PARAM,GRDPNT,0','質量を集計する表を出します。まず部品の追加分を確かめ、それから振動数と形を読みます。']
   ],resultTitle:'質量が増えた場所と、低くなった曲げを照合する',draw:()=>shape('tip-mass'),
   reads:['質量集計表（GPWG）で総質量0.000289952 tを確認します。基準梁との差は0.00008 tです。向き別の質量を3方向分足すと、同じ質量を重複して数えます。','REAL EIGENVECTORでG13のT3が大きい曲げを選び、同じ番号のCYCLESを基準梁と比べます。取り付けた場所が大きく動く形ほど影響を受けるので、総質量の比で全モードを一律に換算できません。','入力タブの操作図と同じ曲げ形を仮定したレイリー近似では、0 gで約38.64 Hz、80 gで約23.89 Hzです。両方とも同じ方法で見積もった比較値です。掲載DATを実行した結果とは区別します。'],
   prompt:'総質量が予定どおりなら、センサーの取り付け位置も正しい？',answer:'同じ80 gを根元に置いても総質量は一致します。CONM2が参照するG13の位置と、曲げたときのその点の動きを確認します。'
  },
  'both-fixed':{
   goals:['右端の変位が0でも、中央に現れる曲げモードを見つけられる。'],
   points:['片持ちの基準梁と同じ部材で、右端も動かないようにする。','両端が止まっていても、その間の節点は上下に動ける。','中央の形と振動数を、片持ちのときの曲げと比べる。'],
   intro:'同じ梁の反対側も治具でつかみます。先端に置いていた変位計は固定端を測ることになり、そこでは揺れが見えません。両端が止まったまま中央が膨らむ形を探します。',
   inputTitle:'拘束点を増やし、観測点を中央へ移す',input:[
    ['SPC=10 → SPC1','G1とG13の移動と回転を止めます。部材の中ほどのG7は拘束しません。'],
    ['MAT1・PBEAM','同じ材質・断面で追加質量はありません。支持を変えても総質量0.000209952 tは同じです。'],
    ['DISPLACEMENT=ALL','モード形を節点ごとに出力します。両端に加え、中央G7のT3を読む準備ができます。']
   ],resultTitle:'両端のゼロと中央の山を一緒に読む',draw:()=>shape('both-fixed'),
   reads:['REAL EIGENVECTORで、同じモード番号のG1・G7・G13のT3を追います。最初の厚さ方向の曲げなら両端は0付近、中央は大きく動きます。','同じモード番号をREAL EIGENVALUESで引き、CYCLESを読みます。両端固定の細長い梁の理論値は約242.31 Hzです。片持ちの番号順をそのまま当てはめず、対応する曲げ方向と形をそろえます。'],
   prompt:'中央G7のT3がほぼゼロなら、梁は振動していない？',answer:'固定端のゼロは拘束で決まります。一方、自由な観測点でも、そのモードで動かない位置（振動の節）ならゼロになります。他の節点や方向も確認して、形全体で判断します。'
  }
 };
 for(const [id,c] of Object.entries(cases)){
  Object.assign(window.AnalysisModelGuides[id],{goals:c.goals,items:c.points});
  const modal=['baseline','tip-mass','both-fixed'].includes(id);
  const readingLinks=modal?'<p>出力要求 DISPLACEMENT は各節点の動きを出します。SOL 103では形を比べるために倍率をそろえます（正規化）。<a href="theory.html#modes">形に一定の倍率を選べる理由 →</a></p>':'<p><a href="theory.html#static">力の釣合いと変形の関係を教材で見る →</a></p>';
  c.input={title:c.inputTitle,body:(c.inputFigure?.()||'')+table(c.input)+readingLinks};
  c.result={title:c.resultTitle,body:()=>c.draw()+c.reads.map(p).join('')+
   '<div class="theory-quiz"><details><summary>'+c.prompt+'</summary>'+p(c.answer)+'</details></div>'};
 }
 window.AnalysisFoundationCases=cases;
})();
